INSERT INTO public.sanctuary_content (id, title, content_type, category, duration, difficulty, creator, origin, story_hook, used_by, sub_type, language, thumbnail_url, steps_count, tags, is_active, display_order, protocol_type, intensity_level, energy_direction, goal_tags, physio_targets, equipment, environment) VALUES
('people-pleasing-boundary-reset','Reset Your Boundaries','micro-practice','pause',4,'intermediate','Brené Brown + Stoic Philosophy + Anna Freud','Vulnerability research + Stoic virtue ethics + Ego psychology','The most exhausted leaders are often the most agreeable. Brown''s research shows that people with clear boundaries are the most compassionate. The Stoics had a word for people-pleasing: ''living for others'' approval.'' They considered it a form of slavery.','CEOs, C-Suite Leaders recognizing a pattern of over-committing, saying yes under pressure, absorbing others'' problems','mindset','en','/assets/recalibrate/pause/people-pleasing-boundary-reset.jpg',4,ARRAY['boundaries','people-pleasing','values','self-respect','leadership'],true,0,'mindset','low','clarify',ARRAY['self_awareness','resilience','clarity','emotional_regulation'],ARRAY['cortisol_reduce','prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home']),
('decision-paralysis-unlock','Break Decision Paralysis','micro-practice','pause',3,'beginner','Dwight Eisenhower + Jeff Bezos + Nassim Taleb','Eisenhower''s decision-making doctrine + Amazon''s one-way/two-way door + Antifragile (Taleb)','Eisenhower commanded operations affecting millions of lives. He said: urgency and importance are not the same thing—and confusing them is the source of most bad decisions. He had a protocol. So did Bezos. So did Taleb. All three agreed: most decisions aren''t as consequential as they feel in the moment.','CEOs, C-Suite Leaders in decision paralysis, option overload, or when the cost of indecision is rising','mindset','en','/assets/recalibrate/pause/decision-paralysis-unlock.jpg',3,ARRAY['decision','paralysis','clarity','leadership','action'],true,0,'mindset','low','clarify',ARRAY['decision_quality','mental_clarity','composure','action'],ARRAY['prefrontal_activation','cortisol_reduce'],ARRAY['none'],ARRAY['private','office','home']),
('mental-block-dissolve','Dissolve the Block','micro-practice','pause',4,'beginner','Steven Pressfield + Carl Jung + Mihaly Csikszentmihalyi','The War of Art (Pressfield) + Jungian Shadow work + Flow theory','Pressfield called it ''The Resistance''—the invisible force that keeps talented people from doing the work that matters. Jung called it the Shadow—the part of us that fears visibility. Both agreed: the block is never about the task. It''s always about something underneath.','CEOs, Executives, Founders hitting creative blocks, procrastinating on high-stakes work','mindset','en','/assets/recalibrate/pause/mental-block-dissolve.jpg',4,ARRAY['mental-block','procrastination','resistance','creativity','start'],true,0,'mindset','low','clarify',ARRAY['mental_clarity','action','resilience','focus'],ARRAY['prefrontal_activation','dopamine_regulation'],ARRAY['none'],ARRAY['private','office','home']),
('creativity-unlock-protocol','Break Out of Linear Thinking','micro-practice','presence',4,'intermediate','Steve Johnson + Edward de Bono + Einstein','Where Good Ideas Come From (Johnson) + Lateral Thinking + Einstein''s thought experiments','Einstein solved relativity by imagining himself riding a beam of light. Jobs got the iPhone''s touchscreen from a PARC engineer''s demonstration. Johnson''s research showed most breakthrough innovations come from unexpected collisions of adjacent ideas—not solitary genius.','CEOs, Founders, C-Suite Leaders who need to generate breakthrough thinking, not incremental improvement','mindset','en','/assets/recalibrate/presence/creativity-unlock-protocol.jpg',4,ARRAY['creativity','innovation','thinking','problem-solving','breakthrough'],true,0,'mindset','low','clarify',ARRAY['creativity','strategic_thinking','mental_clarity','innovation'],ARRAY['prefrontal_activation','dopamine_regulation'],ARRAY['none'],ARRAY['private','office','home']),
('feedback-receive-openly','Receive Feedback Without Shutting Down','micro-practice','presence',3,'intermediate','Ray Dalio + Sheila Heen + Zen Buddhism','Principles (Dalio Radical Transparency) + Thanks for the Feedback (Heen/Stone) + Zen non-attachment','Ray Dalio built Bridgewater''s radical transparency on one insight: the biggest threat to a leader''s effectiveness is their inability to receive accurate information about themselves. Heen''s Harvard research shows that the higher people rise, the less honest feedback they receive—and the less they can receive it.','CEOs, C-Suite Leaders before or after receiving difficult feedback, performance reviews, board assessments','mindset','en','/assets/recalibrate/presence/feedback-receive-openly.jpg',3,ARRAY['feedback','growth','leadership','self-awareness','transparency'],true,0,'mindset','low','clarify',ARRAY['self_awareness','resilience','growth','composure'],ARRAY['cortisol_reduce','prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home']),
('high-stakes-judgment-clarity','Debias a Major Judgment Call','micro-practice','presence',4,'intermediate','Charlie Munger + Daniel Kahneman + Stoic Philosophy','Poor Charlie''s Almanack + Thinking, Fast and Slow + Stoic rationality','Charlie Munger keeps a mental checklist of cognitive biases. He reviews it before every significant decision. Kahneman proved that humans are systematically irrational under pressure. The best decisions come not from smarter people—but from people with cleaner cognitive processes.','CEOs, C-Suite Leaders before significant judgment calls—hiring, firing, acquisitions, strategic pivots','mindset','en','/assets/recalibrate/presence/high-stakes-judgment-clarity.jpg',4,ARRAY['judgment','decision','bias','leadership','clarity'],true,0,'mindset','low','clarify',ARRAY['decision_quality','clarity','strategic_thinking','wisdom'],ARRAY['prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home']),
('courage-activation-threshold','Take the Courageous Action','micro-practice','power-up',3,'intermediate','Brene Brown + Winston Churchill + Navy SEAL Training Philosophy','Daring Greatly (Brown) + Churchill''s wartime speeches + SEAL Hell Week psychology','Churchill said: ''Courage is what it takes to stand up and speak.'' The most courageous acts in leadership are often not the dramatic ones—they''re the ones where you say the uncomfortable truth, take the unpopular position, or make the bold move when no one else will.','CEOs, C-Suite Leaders at the edge of a courageous action—a difficult truth to speak, a bold strategic bet','mindset','en','/assets/recalibrate/power-up/courage-activation-threshold.jpg',3,ARRAY['courage','bold','action','leadership','fear'],true,0,'mindset','medium','uplift',ARRAY['courage','confidence','resilience','action'],ARRAY['cortisol_reduce','hrv_increase','prefrontal_activation'],ARRAY['none'],ARRAY['private','office','home']),
('momentum-generator-stuck','Break the Inertia','micro-practice','power-up',3,'beginner','Newton + Tony Robbins + James Clear','Physics of inertia (Newton) + Motivational science + Atomic Habits / behavior design (Clear/Fogg)','Newton''s first law applies to humans as much as objects: a body at rest stays at rest. A body in motion stays in motion. The most powerful thing any leader can do when stuck is create motion—any motion. The direction can be corrected; stillness cannot.','CEOs, Founders, C-Suite Leaders stuck in inertia on important work, projects, or decisions','mindset','en','/assets/recalibrate/power-up/momentum-generator-stuck.jpg',3,ARRAY['momentum','inertia','start','action','motivation'],true,0,'mindset','medium','uplift',ARRAY['action','motivation','energy','focus'],ARRAY['dopamine_regulation','hrv_increase'],ARRAY['none'],ARRAY['private','office','home']),
('performance-state-activation','Create Your Peak State','micro-practice','power-up',4,'intermediate','Tony Robbins + Psychophysiology Research + Olympic Sport Psychology','State management methodology + HRV research + Pre-competition priming protocols','Olympians don''t wait to feel their best on competition day. They have protocols to create their best state on command. Navy SEALs are trained to shift physiological state within minutes—because missions don''t wait for optimal feelings.','CEOs, C-Suite Leaders before critical performance moments','mindset','en','/assets/recalibrate/power-up/performance-state-activation.jpg',4,ARRAY['performance','state','peak','energy','activation'],true,0,'mindset','high','uplift',ARRAY['energy','confidence','focus','performance'],ARRAY['hrv_increase','dopamine_regulation','cortisol_reduce'],ARRAY['none'],ARRAY['private','office','home'])
INSERT INTO public.sanctuary_content_metadata (id, content_id, structured_tags, completion_quote, intro_summary, essence, parallel, cue, why_this_works, mastery_category, horizon, meta_skill, is_foundational, moment, state_signal, duration_band) VALUES
(gen_random_uuid(),'people-pleasing-boundary-reset','{"pillar": "pause", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["Pattern of saying yes when you mean no", " feeling resentful", " over-extended", " managing others emotions at cost of your effectiveness"], "goalTags": ["self_awareness", "resilience", "clarity", "emotional_regulation"], "physioTarget": ["cortisol_reduce", "prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','Your boundary is your integrity. You chose integrity.','When you keep saying yes when you mean no. Choose integrity over approval.','A boundary is not a wall. It''s a statement of what you can genuinely give.','Differentiation of self (Bowen systems); Stoic freedom from opinion (Epictetus); Values-based decision making (ACT)','My ''no'' protects the value of my ''yes''.','People-pleasing is a threat-avoidance strategy—we say yes to avoid discomfort of disapproval. Each yes erodes trust in yourself. This protocol builds values-based decisions rather than comfort-based decisions.','{"primary": "meta-recalibration", "secondary": ["pause", "meta-clarity"]}','{tactical,strategic}','{meta-recalibration,meta-clarity}',false,'{moment-post-meeting,moment-evening-close}','{signal-depleted,signal-body-under-load}','short'),
(gen_random_uuid(),'decision-paralysis-unlock','{"pillar": "pause", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["Stuck on a decision", " multiple options feel equally weighted", " fear of making the wrong call", " over-analyzing"], "goalTags": ["decision_quality", "mental_clarity", "composure", "action"], "physioTarget": ["prefrontal_activation", "cortisol_reduce"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','The decision is made. You move forward with it.','Stuck on a decision too long. Classify, decide, and move forward.','A decision made is almost always better than a decision deferred. The cost of not deciding is a decision.','Satisficing (Simon); Regret Minimization (Bezos); 70% rule (Bezos on Amazon decisions)','I decide now with what I have. Imperfect action beats perfect inaction.','Decision paralysis comes from treating reversible decisions as irreversible. This protocol classifies by reversibility and consequence, reducing emotional weight and activating the prefrontal cortex rather than the threat-detection amygdala.','{"primary": "meta-clarity", "secondary": ["pause"]}','{immediate}','{meta-clarity}',false,'{moment-crisis,moment-pre-jit}','{signal-clarity-low,signal-depleted}','micro'),
(gen_random_uuid(),'mental-block-dissolve','{"pillar": "pause", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["Mental block", " procrastination", " can''t begin the work that matters despite knowing it''s important"], "goalTags": ["mental_clarity", "action", "resilience", "focus"], "physioTarget": ["prefrontal_activation", "dopamine_regulation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You named the wall and walked through it.','Stuck, procrastinating, can''t start. Get through the resistance and into the work.','The block is information. What it''s guarding is more interesting than the block itself.','Resistance (Pressfield); Activation energy theory; Imposter syndrome (Clance & Imes); Shadow integration (Jung)','The block points to what matters. I move through it.','Mental blocks are protection mechanisms—the nervous system protecting you from perceived exposure, failure, or judgment. Naming what''s beneath the block shifts it from automatic threat-avoidance to a conscious choice. The ''two-minute start'' exploits how the brain''s reward system is triggered by starting, not completing.','{"primary": "meta-clarity", "secondary": ["pause", "meta-recalibration"]}','{immediate}','{meta-clarity,meta-recalibration}',false,'{moment-pre-jit,moment-crisis}','{signal-clarity-low,signal-depleted}','short'),
(gen_random_uuid(),'creativity-unlock-protocol','{"pillar": "flow", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["Stuck in linear thinking on a problem that needs a fundamentally different solution"], "goalTags": ["creativity", "strategic_thinking", "mental_clarity", "innovation"], "physioTarget": ["prefrontal_activation", "dopamine_regulation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You found the door that wasn''t there before.','Stuck thinking about a problem the same way. Find the angle you haven''t seen yet.','The answer is never where you''re looking. It''s always one step to the side.','Lateral thinking (de Bono); Adjacent possible (Johnson); First principles (Musk); Beginner''s mind (Suzuki Roshi)','What if everything I know about this is wrong?','Creative breakthroughs require temporary suspension of existing mental models. Deliberate constraint, perspective-shifting, and analogical thinking force the brain out of habitual neural pathways.','{"primary": "meta-clarity", "secondary": ["presence"]}','{tactical,strategic}','{meta-clarity}',false,'{moment-pre-jit,moment-post-meeting}','{signal-clarity-low}','short'),
(gen_random_uuid(),'feedback-receive-openly','{"pillar": "flow", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["About to receive significant feedback", " or processing critical feedback just received"], "goalTags": ["self_awareness", "resilience", "growth", "composure"], "physioTarget": ["cortisol_reduce", "prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You stayed open. That is how growth happens.','Before or after a hard review. Separate the information from the identity threat.','The leader who cannot be told anything cannot grow. Permeability is a superpower.','Radical transparency (Dalio); Non-defensive receiving (Heen); Mushin (Zen—no-mind); Growth mindset (Dweck)','This is data. I am not the data.','Critical feedback triggers the same threat response as physical danger. Pre-activating the ''observer self'' means feedback is received as information rather than threat. Dalio''s research confirms: leaders who can receive accurate feedback make significantly better decisions.','{"primary": "meta-recalibration", "secondary": ["presence"]}','{tactical}','{meta-recalibration}',false,'{moment-pre-jit,moment-post-meeting}','{signal-confidence-low,signal-tense}','micro'),
(gen_random_uuid(),'high-stakes-judgment-clarity','{"pillar": "flow", "intensityLevel": "low", "energyDirection": "clarify", "contextTags": ["About to make a consequential judgment call and want to ensure the thinking is clean", " not contaminated"], "goalTags": ["decision_quality", "clarity", "strategic_thinking", "wisdom"], "physioTarget": ["prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','Your lens is clean. The judgment is yours.','Before consequential decisions. Run a cognitive bias scan so you''re deciding — not rationalizing.','The best decisions come from clean lenses, not superior intelligence.','Cognitive bias checklist (Munger); Debiasing (Kahneman/Lovallo); Prospective hindsight; Adversarial collaboration','What do I not want to be true? That''s what I need to examine.','Most bad executive decisions are caused by cognitive contamination—confirmation bias, sunk cost fallacy, social pressure, or emotional flooding. This protocol runs a rapid debiasing scan before judgment.','{"primary": "meta-clarity", "secondary": ["presence"]}','{tactical}','{meta-clarity}',false,'{moment-pre-jit}','{signal-clarity-low}','short'),
(gen_random_uuid(),'courage-activation-threshold','{"pillar": "renewal", "intensityLevel": "medium", "energyDirection": "uplift", "contextTags": ["Standing at the threshold of a courageous action and feeling the pull to retreat to safety"], "goalTags": ["courage", "confidence", "resilience", "action"], "physioTarget": ["cortisol_reduce", "hrv_increase", "prefrontal_activation"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You moved. That is what courage looks like.','Standing at the threshold of a brave move. Feel the fear and make the move anyway.','Courage is not the absence of fear. It''s moving forward with it.','Vulnerability research (Brown); Courage training (SEALs); Memento Mori practice; Regret minimization (Bezos)','I feel it. I move anyway.','Courage is a skill, not a trait—it''s trained through repeated acts of moving through fear. This protocol uses regulatory breathing, cognitive reframing, and commitment anchoring to convert intention to action.','{"primary": "meta-renewal", "secondary": ["power-up"]}','{immediate}','{meta-renewal}',false,'{moment-pre-jit,moment-crisis}','{signal-confidence-low,signal-tense}','micro'),
(gen_random_uuid(),'momentum-generator-stuck','{"pillar": "renewal", "intensityLevel": "medium", "energyDirection": "uplift", "contextTags": ["Stuck", " can''t begin the work that matters", " inertia on important work"], "goalTags": ["action", "motivation", "energy", "focus"], "physioTarget": ["dopamine_regulation", "hrv_increase"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','You broke the inertia. Motion generates momentum.','Stuck and can''t begin the work that matters. One small move to break the standstill.','The first move doesn''t have to be right. It has to be a move.','Tiny habits (Fogg); 2-minute rule (Clear); Activation energy reduction; Do it now (special operations)','Motion before perfection. Forward before ready.','Inertia is a neurological state—the brain''s threat system interprets beginning as exposure to potential failure. Creating motion triggers the brain''s reward system (dopamine on task initiation), making continuation progressively easier.','{"primary": "meta-renewal", "secondary": ["power-up"]}','{immediate}','{meta-renewal}',false,'{moment-pre-jit}','{signal-low-energy,signal-depleted}','micro'),
(gen_random_uuid(),'performance-state-activation','{"pillar": "renewal", "intensityLevel": "high", "energyDirection": "uplift", "contextTags": ["Need peak performance state now \u2014 important meeting", " presentation", " negotiation", " in the next 15 minutes"], "goalTags": ["energy", "confidence", "focus", "performance"], "physioTarget": ["hrv_increase", "dopamine_regulation", "cortisol_reduce"], "equipment": ["none"], "environmentSuitability": ["office", "home", "private"], "socialTag": "solo"}','State created. You are ready. Perform.','When you need to perform at your best in the next 15 minutes. Activate the state deliberately.','Peak performance is a state you can learn to enter, not one that visits you randomly.','Peak performance protocols (sport psychology); Flow induction; State-dependent performance; Autonomic nervous system regulation','I am creating the state. The state creates the performance.','States are bidirectional—the body influences the mind as much as the mind influences the body. By deliberately changing physiology (breath, posture, movement), you change neurochemistry, which changes cognitive and emotional state.','{"primary": "meta-renewal", "secondary": ["power-up"]}','{immediate}','{meta-renewal}',false,'{moment-pre-jit}','{signal-low-energy,signal-depleted}','short');
INSERT INTO public.sanctuary_content_steps (id, content_id, step_order, title, instruction, duration, breathing_pattern, wisdom_note) VALUES
(gen_random_uuid(),'people-pleasing-boundary-reset',1,'Name the Pattern','What are you about to agree to that part of you wants to decline? Say it aloud or write it. What is the feared consequence of saying no? Name it specifically—''They''ll think I''m not a team player.'' Epictetus: if it concerns others'' opinion, it''s not yours to control.',60,NULL,'You suffer more from imagination than reality. Name the fear exactly.'),
(gen_random_uuid(),'people-pleasing-boundary-reset',2,'Check Your Values','Ask: ''Does saying yes to this align with my actual priorities right now?'' Is this a yes that serves the work, or a yes that serves your need to be liked?',60,NULL,'A great leader''s highest obligation is not approval—it''s effectiveness.'),
(gen_random_uuid(),'people-pleasing-boundary-reset',3,'Craft the Honest Response','Practice saying it: ''I can''t give this the attention it deserves right now.'' No apology, no over-explanation. Brown: over-explaining is a tell that you still seek approval. One clean sentence.',60,NULL,'The cleaner the boundary, the greater the respect it earns.'),
(gen_random_uuid(),'people-pleasing-boundary-reset',4,'Tolerate the Discomfort','Sit with the feeling that follows a genuine ''no'' for 30 seconds. Notice it''s discomfort—not danger. Your nervous system has been trained to treat disapproval as threat. This moment is re-training it.',30,'4 in, 6 out','Each time you choose integrity over approval, you become more of who you are.'),
(gen_random_uuid(),'decision-paralysis-unlock',1,'Classify the Decision','Ask: ''Is this a one-way door (irreversible) or a two-way door (reversible)?'' Be honest. Most decisions are two-way doors. Bezos''s rule: two-way doors should be made fast, with 70% of the information you''d want.',45,NULL,'Treat two-way doors like two-way doors. Most of your anguish is misclassification.'),
(gen_random_uuid(),'decision-paralysis-unlock',2,'Name Your Best Option Right Now','With what you currently know, what is the best available option? Not the perfect option—the best of what exists. Write it in one sentence.',60,NULL,'The enemy of a good plan is the dream of a perfect plan. — Von Clausewitz'),
(gen_random_uuid(),'decision-paralysis-unlock',3,'Decide and Record','State your decision out loud or write it down. Add: ''I''m making this decision based on ___. If it proves wrong, I''ll know by ___.'' This creates a decision log and closes the loop neurologically.',45,NULL,'A king who decides is followed. A king who deliberates is abandoned.'),
(gen_random_uuid(),'mental-block-dissolve',1,'Name the Specific Block','Complete this: ''I keep avoiding ___ because if I do it and it goes badly, ___.'' Say the fear out loud. Pressfield: the Resistance always points toward your most important work. The block confirms significance.',60,NULL,'The more important the creative work, the more Resistance you feel. — Pressfield'),
(gen_random_uuid(),'mental-block-dissolve',2,'Separate the Real from the Catastrophic','Ask: ''Is the consequence I''m imagining likely? What actually happens if it doesn''t go perfectly?'' Map the realistic worst case. In most cases, it''s recoverable.',60,NULL,'Most of what you fear never arrives. And when it does, you handle it.'),
(gen_random_uuid(),'mental-block-dissolve',3,'Make the Minimum Move','What is the smallest possible action that counts as starting? Not completing—just starting. Write the first sentence. Open the document. Commit to two minutes only.',60,NULL,'You don''t have to see the whole staircase—just take the first step. — MLK'),
(gen_random_uuid(),'mental-block-dissolve',4,'Start Now','Without doing anything else: start the minimum move you identified. Now. The protocol''s entire purpose is the next two minutes of action.',30,NULL,'Action dissolves fear. Preparation feeds it.'),
(gen_random_uuid(),'creativity-unlock-protocol',1,'State the Problem as a Question','Write your challenge as a question: not ''we need more revenue'' but ''what would have to be true for us to grow 10x without scaling headcount?'' Better questions generate better thinking.',45,NULL,'The quality of your answers is determined by the quality of your questions.'),
(gen_random_uuid(),'creativity-unlock-protocol',2,'Apply the First Principles Strip','Ask: ''What do I KNOW is true? What do I ASSUME is true?'' Strip everything that''s assumption. What remains is bedrock. Musk built SpaceX by refusing to accept rockets had to be expensive.',75,NULL,'First principles: reason from the ground up, not from analogy. — Elon Musk'),
(gen_random_uuid(),'creativity-unlock-protocol',3,'The Perspective Shift','Ask: ''How would a 10-year-old describe this problem? How would a Zen monk approach it? How did someone in a different industry solve something similar?'' Pick one. Think from inside that perspective for 60 seconds.',60,NULL,'Creative thinking is the temporary adoption of a foreign mind.'),
(gen_random_uuid(),'creativity-unlock-protocol',4,'Name the Adjacent Idea','What''s one idea from a completely different domain that connects to this problem unexpectedly? Write it. Don''t evaluate yet—just name it.',45,NULL,'The most creative act is not invention—it''s connection.'),
(gen_random_uuid(),'feedback-receive-openly',1,'Separate Identity from Information','Before feedback arrives, say internally: ''I am not my performance. I am the person who can learn from it.'' Draw a mental line between who you are and what you''ve done.',45,NULL,'Your identity is not an outcome. Your identity is who chooses how to respond.'),
(gen_random_uuid(),'feedback-receive-openly',2,'Set the Learner''s Frame','Ask yourself: ''What is the most useful thing I could discover today?'' This shifts you from defense mode to discovery mode. Heen''s research: the single question that most improves feedback receptivity.',45,NULL,'The best leaders are the best learners. They''ve never stopped being students.'),
(gen_random_uuid(),'feedback-receive-openly',3,'Listen for the Grain of Truth','During feedback: your one job is to find the grain of truth even in the most clumsily delivered message. Don''t debate. Don''t explain. Just listen for what''s accurate. Even 10% accuracy is valuable.',45,NULL,'You don''t have to agree with everything to learn from everything.'),
(gen_random_uuid(),'high-stakes-judgment-clarity',1,'Name the Decision Precisely','Write: ''The judgment I''m making is ___.'' One sentence. Fuzzy decisions produce fuzzy thinking. Munger: always state the question precisely before attempting to answer it.',45,NULL,'A well-defined problem is half-solved.'),
(gen_random_uuid(),'high-stakes-judgment-clarity',2,'Run the Bias Scan','Ask yourself each in 20 seconds: ''Am I looking for evidence to confirm what I already believe? Am I influenced by who is presenting this? Am I avoiding a conclusion because it''s socially painful?'' Name any that apply.',75,NULL,'Munger: if you know your biases by name, they lose half their power over you.'),
(gen_random_uuid(),'high-stakes-judgment-clarity',3,'Steel the Opposite Case','Spend 60 seconds making the best possible argument AGAINST your current conclusion. Genuinely try to find what''s right about the opposing view. Kahneman calls this ''adversarial collaboration.''',60,NULL,'The most dangerous words in a boardroom: ''I think I already know the answer.'''),
(gen_random_uuid(),'high-stakes-judgment-clarity',4,'Name Your Confidence Level','On a scale of 1-10, how confident are you in this judgment and what is that confidence based on? If above 8: ask what you''re missing. High confidence under uncertainty is a bias flag.',45,NULL,'The goal is calibrated certainty, not comfortable certainty.'),
(gen_random_uuid(),'courage-activation-threshold',1,'Name the Fear Precisely','What specifically are you afraid will happen if you take this action? Not generally—specifically. ''I''m afraid they''ll think less of me'' is more workable than ''I''m just afraid.'' Vague fear is the most dangerous kind.',45,NULL,'Fear unnamed is fear at full power. Name it exactly.'),
(gen_random_uuid(),'courage-activation-threshold',2,'Apply the Regret Test','Bezos: ''At 80, will I regret not doing this?'' In most cases of genuine courage, the regret of not acting vastly exceeds the discomfort of acting. Name what you''d regret.',45,NULL,'The cost of courage is discomfort. The cost of cowardice is regret. Which is larger?'),
(gen_random_uuid(),'courage-activation-threshold',3,'Breathe and Step','Three power breaths: sharp in through the nose (4 counts), hold (2), exhale sharply through the mouth (2). Feel the shift. Then take the action. Now. The moment of hesitation is the precise moment courage is required.',45,'4 in, 2 hold, 2 sharp out x3','SEALs say: the only easy day was yesterday. The hard thing is always worth it.'),
(gen_random_uuid(),'momentum-generator-stuck',1,'Name the Object in Inertia','What is the specific thing that is stuck? Be precise. ''I need to start the strategy deck.'' Not ''I need to do more strategic thinking.'' The smaller and more specific the target, the more likely you are to begin.',45,NULL,'You cannot move a vague thing. Make it specific before you try.'),
(gen_random_uuid(),'momentum-generator-stuck',2,'Find the Atomic Start','What is the smallest possible version of starting? Not the complete action—just the door. Open the document. Write the title. Atomic habits: if you can make the initiation cost less than 2 minutes, it nearly always happens.',45,NULL,'The hardest part is not the work—it''s crossing the threshold. Minimize the threshold.'),
(gen_random_uuid(),'momentum-generator-stuck',3,'Start Right Now','Set a timer for 10 minutes. Begin the atomic start immediately. Don''t plan the whole thing. Commit only to 10 minutes. Newton''s law: once in motion, you will likely continue beyond the 10 minutes.',45,NULL,'Movement generates momentum. Momentum generates movement. One step breaks the pattern.'),
(gen_random_uuid(),'performance-state-activation',1,'Diagnose Your Current State','On a 1-10 scale: where is your energy? Where is your focus? Where is your confidence? You cannot calibrate without honest diagnosis. If you''re at 4-5 and need 8-9, you have a specific state change to make in the next 4 minutes.',45,NULL,'You cannot navigate without knowing where you currently are.'),
(gen_random_uuid(),'performance-state-activation',2,'Shift the Physiology','Choose one: stand and take 10 power breaths (sharp in, full out); do 20 seconds of vigorous movement; take a 30-second cold water splash. These are physiological primers—they change your chemistry before your psychology catches up.',60,'Physiological primer','The body leads. The mind follows. Change the body first.'),
(gen_random_uuid(),'performance-state-activation',3,'Install the Peak Reference','Close your eyes. Remember the most alive, capable, confident you''ve ever felt. What were you doing? What did your body feel like? Stay with this for 30 seconds—don''t just think it, FEEL it. Your nervous system is being primed with your best pattern.',60,NULL,'The mind can access past peak states—and use them to prime future ones.'),
(gen_random_uuid(),'performance-state-activation',4,'Lock It In and Go','Open your eyes. Take one decisive breath. Say your name and the task: ''___, you are ready for ___.'' Walk directly into the performance. You''re already in state. Now perform.',30,NULL,'Pre-performance doubt is the enemy of performance. Decide you''re ready and be right.');